<?php
require_once __DIR__.'/includes/functions.php';require_role(['admin']);$page_title='Reports';
$byType=$pdo->query("SELECT type,COUNT(*) total FROM resources WHERE status='approved' GROUP BY type")->fetchAll();$byMonth=$pdo->query("SELECT DATE_FORMAT(created_at,'%Y-%m') month,COUNT(*) total FROM resources GROUP BY DATE_FORMAT(created_at,'%Y-%m') ORDER BY month DESC LIMIT 12")->fetchAll();$top=$pdo->query("SELECT r.title,r.type,COUNT(d.id) downloads FROM resources r LEFT JOIN downloads d ON d.resource_id=r.id WHERE r.status='approved' GROUP BY r.id ORDER BY downloads DESC LIMIT 10")->fetchAll();$activity=$pdo->query("SELECT a.*,u.name FROM activity_logs a JOIN users u ON u.id=a.user_id ORDER BY a.created_at DESC LIMIT 20")->fetchAll();require __DIR__.'/includes/header.php';?>
<section class="page-heading"><span class="eyebrow">PLATFORM INSIGHTS</span><h1>Reports & analytics</h1><p>Monitor resource contributions and community usage.</p></section>
<div class="two-col"><section class="panel"><h2>Approved resources by category</h2><?php foreach($byType as $x): ?><div class="bar-row"><span><?= e(ucwords(str_replace('_',' ',$x['type']))) ?></span><b><?= (int)$x['total'] ?></b><div class="bar"><i style="width:<?= min(100,(int)$x['total']*10) ?>%"></i></div></div><?php endforeach; ?></section><section class="panel"><h2>Recent upload activity</h2><?php foreach($byMonth as $x): ?><div class="list-row"><span><?= e($x['month']) ?></span><b><?= (int)$x['total'] ?> uploads</b></div><?php endforeach; ?></section></div>
<section class="panel"><h2>Most downloaded resources</h2><div class="table-wrap"><table><thead><tr><th>Resource</th><th>Category</th><th>Downloads</th></tr></thead><tbody><?php foreach($top as $x): ?><tr><td><?= e($x['title']) ?></td><td><?= e($x['type']) ?></td><td><?= (int)$x['downloads'] ?></td></tr><?php endforeach; ?></tbody></table></div></section>
<section class="panel"><h2>Recent platform activity</h2><div class="table-wrap"><table><thead><tr><th>User</th><th>Action</th><th>Date</th></tr></thead><tbody><?php foreach($activity as $x): ?><tr><td><?= e($x['name']) ?></td><td><?= e($x['action']) ?></td><td><?= e($x['created_at']) ?></td></tr><?php endforeach; ?></tbody></table></div></section>
<?php require __DIR__.'/includes/footer.php';?>